export function getRomanianCountyName(code: string): string {
  return ROMANIAN_COUNTIES[code]?.[0] || code;
}

export function getRomanianCities(countyCode: string): { name: string; latitude: string; longitude: string; type: string }[] {
  const county = ROMANIAN_COUNTIES[countyCode];
  if (!county) return [];
  return county[1].map(([name, latitude, longitude, type]) => ({ name, latitude, longitude, type }));
}

export function getRomanianCityCoordinates(countyCode: string, cityName: string): { lat: number; lng: number } | null {
  const county = ROMANIAN_COUNTIES[countyCode];
  if (!county) return null;
  const city = county[1].find(([name]) => name === cityName);
  if (!city || !city[1] || !city[2]) return null;
  return { lat: Number(city[1]), lng: Number(city[2]) };
}

